import{_ as a,o as l,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph S3 – Dynamic Placement and Optimized Retention","description":"","frontmatter":{"title":"Ceph S3 – Dynamic Placement and Optimized Retention","date":"2026-04-02T00:00:00.000Z","updated":"2026-04-03T00:00:00.000Z","tags":["Ceph","RGW","object storage","S3","lifecycle policy"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_S3_Dynamic_Placement_and_Optimized_Retention.md","filePath":"posts/2026/Ceph_S3_Dynamic_Placement_and_Optimized_Retention.md","lastUpdated":1780459816000}'),t={name:"posts/2026/Ceph_S3_Dynamic_Placement_and_Optimized_Retention.md"};function r(c,e,n,s,d,p){return l(),i("div",null,[...e[0]||(e[0]=[o('<h2 id="演讲背景" tabindex="-1">演讲背景 <a class="header-anchor" href="#演讲背景" aria-label="Permalink to &quot;演讲背景&quot;">​</a></h2><p>本次演讲来自一位在高等教育与科研环境中工作超过 20 年、自 2014 年（Firefly 版本）起便深度使用 Ceph 的工程师。演讲主题聚焦于 Ceph S3（即 RGW/radosgw）的动态数据放置（Dynamic Placement）与优化数据保留（Optimized Retention）两大核心能力。</p><h2 id="一、s3-storage-classes-与-placement-targets" tabindex="-1">一、S3 Storage Classes 与 Placement Targets <a class="header-anchor" href="#一、s3-storage-classes-与-placement-targets" aria-label="Permalink to &quot;一、S3 Storage Classes 与 Placement Targets&quot;">​</a></h2><p>Ceph 集群支持配置多个 S3 storage classes，每个 storage class 可以映射到不同的 pool 和数据放置策略。常见的差异化维度包括：</p><ul><li><strong>性能</strong>：NVMe SD vs HDD</li><li><strong>访问频率</strong>：热数据 vs 冷数据</li><li><strong>持久性与成本</strong>：replication pool vs erasure coding pool</li><li><strong>压缩</strong>：可借助 Intel QAT 等硬件卸载压缩计算</li></ul><p>S3 客户端在写入对象时可以指定 storage class，但实际场景中客户端经常不指定，或定不当。这正是动态放置需要解决的问题。</p><h2 id="二、dynamic-placement-lua-脚本驱动的动态存储类分配" tabindex="-1">二、Dynamic Placement：Lua 脚本驱动的动态存储类分配 <a class="header-anchor" href="#二、dynamic-placement-lua-脚本驱动的动态存储类分配" aria-label="Permalink to &quot;二、Dynamic Placement：Lua 脚本驱动的动态存储类分配&quot;">​</a></h2><h3 id="核心思路" tabindex="-1">核心思路 <a class="header-anchor" href="#核心思路" aria-label="Permalink to &quot;核心思路&quot;">​</a></h3><p>当客户端未指定 storage class，或指定不合理时，RGW 可以通过 Lua 脚本在请求处理过程中自动为对象分配合适的 storage class。</p><h3 id="可用的判断维度" tabindex="-1">可用的判断维度 <a class="header-anchor" href="#可用的判断维度" aria-label="Permalink to &quot;可用的判断维度&quot;">​</a></h3><ul><li>对象扩展名（如 <code>.mp4</code>、<code>.pdf</code>）</li><li>对象大小（如是否超过 1 MB、2 MB 阈值）</li><li>Tenant 名称</li><li>Bucket 名称</li><li>上传方式（multipart upload vs单次 PUT）</li></ul><h3 id="lua-脚本执行时机" tabindex="-1">Lua 脚本执行时机 <a class="header-anchor" href="#lua-脚本执行时机" aria-label="Permalink to &quot;Lua 脚本执行时机&quot;">​</a></h3><p>RGW 支持在以下请求阶段执行 Lua 脚本：</p><ul><li><code>pre-request</code></li><li><code>post-request</code></li><li><code>background</code></li><li><code>get data</code> / <code>put data</code></li></ul><p>脚本可以读取并修改对象的 metadata，从而在写入时动态设置 storage class，确保存储效率和访问性能从数据落盘的第一刻起就得到保障。</p><h3 id="典型用例-vm-备份与恢复" tabindex="-1">典型用例：VM 备份与恢复 <a class="header-anchor" href="#典型用例-vm-备份与恢复" aria-label="Permalink to &quot;典型用例：VM 备份与恢复&quot;">​</a></h3><p>以 VM backup and replication 软件为例：</p><ul><li>数据对象大小通常在 1 MB 到 8 MB 之间</li><li>索引、日志、指针等元数据对象大小仅为 0 字节到 64 KB</li></ul><p>Lua 脚本可以将小对象路由到 replicated pool（低延迟），将大对象路由到 erasure coding pool（高效率），实现自动分层。</p><h3 id="其他-lua-脚本用例" tabindex="-1">其他 Lua 脚本用例 <a class="header-anchor" href="#其他-lua-脚本用例" aria-label="Permalink to &quot;其他 Lua 脚本用例&quot;">​</a></h3><ul><li>在 bucket ACL 之上增加额外的访问控制层（如强制只读或只写），防止 ACL 配置错误导致数据泄露</li><li>为特定 bucket 的请求添加追踪日志</li><li>在客户端未指定时自动补充默认 metadata</li><li>仅在发生错误时记录操作日志</li><li>采集操作 trace 用于分析</li></ul><h3 id="lua-性能与可靠性" tabindex="-1">Lua 性能与可靠性 <a class="header-anchor" href="#lua-性能与可靠性" aria-label="Permalink to &quot;Lua 性能与可靠性&quot;">​</a></h3><ul><li>初步测试显示 Lua 脚本引入的延迟极低，通常在微秒级别</li><li>每个执行上下文最多消耗约 120 KB RAM（可通过配置调整）</li><li>脚本超时默认为 1 秒；脚本执行失败（超时或语法错误）对 S3 客户端请求是<strong>非致命的</strong>，客户端会收到正常响应，如同脚本未执行</li><li>近期合并的优化：通过缓存 Lua 字节码来提升性能，同时减少读取存储 Lua 脚本的 RADOS 对象所需的网络调用次数</li></ul><h2 id="三、optimized-retention-基于-lifecycle-policy-的优化数据保留" tabindex="-1">三、Optimized Retention：基于 Lifecycle Policy 的优化数据保留 <a class="header-anchor" href="#三、optimized-retention-基于-lifecycle-policy-的优化数据保留" aria-label="Permalink to &quot;三、Optimized Retention：基于 Lifecycle Policy 的优化数据保留&quot;">​</a></h2><h3 id="lifecycle-policy-的过渡条件" tabindex="-1">Lifecycle Policy 的过渡条件 <a class="header-anchor" href="#lifecycle-policy-的过渡条件" aria-label="Permalink to &quot;Lifecycle Policy 的过渡条件&quot;">​</a></h3><p>Ceph Squid 版本新增了基于对象大小的过渡条件：</p><ul><li><code>object size greater than</code></li><li><code>object size less than</code></li></ul><p>即使在写入时未使用 Lua 脚本，也可以通过 lifecycle policy 将数据从 replicated pool 迁移到 erasure coding pool，或反向迁移。</p><h3 id="压缩与解压缩联动" tabindex="-1">压缩与解压缩联动 <a class="header-anchor" href="#压缩与解压缩联动" aria-label="Permalink to &quot;压缩与解压缩联动&quot;">​</a></h3><p>本周（演讲当周）社区合并了一个新特性：在 lifecycle过渡时同步执行压缩或解压缩。此前存在一个问题：对象从一个 storage class 过渡到另一个启用了压缩的 storage class 时，压缩并不会被应用。经过与社区成员（Casey、Matthew Eller）的快速讨论，当天即完成了修复，是社区高效协作的典型案例。</p><h3 id="其他-lifecycle-能力" tabindex="-1">其他 Lifecycle 能力 <a class="header-anchor" href="#其他-lifecycle-能力" aria-label="Permalink to &quot;其他 Lifecycle 能力&quot;">​</a></h3><ul><li>过期非当前版本（non-current versions），同时保留指定数量的历史版本</li><li>自动清理未完成的 multipart upload 分片（tailed/incomplete parts）</li><li>支持通过 tag 或 prefix 选择性地应用 lifecycle 规则</li></ul><blockquote><p><strong>注意</strong>：lifecycle 的expire 规则会永久删除数据，使用时务必谨慎。建议配合 versioning 使用，并至少保留一个版本。</p></blockquote><h2 id="四、配置方法" tabindex="-1">四、配置方法 <a class="header-anchor" href="#四、配置方法" aria-label="Permalink to &quot;四、配置方法&quot;">​</a></h2><h3 id="pool-与-storage-class-配置" tabindex="-1">Pool 与 Storage Class 配置 <a class="header-anchor" href="#pool-与-storage-class-配置" aria-label="Permalink to &quot;Pool 与 Storage Class 配置&quot;">​</a></h3><ol><li>创建多个 pool，配置不同的 erasure coding profile</li><li>使用 <code>radosgw-admin zonegroup</code> 命令将新 storage class 添加到 zone group</li><li>将 storage class 绑定到对应的 pool，并配置是否启用压缩</li></ol><h3 id="lua-脚本配置方式" tabindex="-1">Lua 脚本配置方式 <a class="header-anchor" href="#lua-脚本配置方式" aria-label="Permalink to &quot;Lua 脚本配置方式&quot;">​</a></h3><p><strong>方式一（静态）</strong>：将规则直接写入 RGW 服务配置，重启 RGW 后生效。</p><p><strong>方式二（动态）</strong>：在 RGW 配置中引用本地文件系统路径，规则配置文件可在不重启 RGW 的情况下直接修改，实时生效。</p><h3 id="lifecycle-配置" tabindex="-1">Lifecycle 配置 <a class="header-anchor" href="#lifecycle-配置" aria-label="Permalink to &quot;Lifecycle 配置&quot;">​</a></h3><p>使用 AWS S3 兼容命令（如 <code>put-bucket-lifecycle-configuration</code>）按 bucket 粒度上传 lifecycle 配置文件。</p><h3 id="调试与验证" tabindex="-1">调试与验证 <a class="header-anchor" href="#调试与验证" aria-label="Permalink to &quot;调试与验证&quot;">​</a></h3><ul><li>使用 <code>debug rgw 20</code> 查看 Lua 脚本执行的详细 trace 和日志</li><li>使用 <code>rados df</code> 和 <code>ceph df</code> 监控各 pool 的对象数量和容量占用</li><li>使用 <code>rgw_lc_debuginterval=1</code> 加速 lifecycle 测试（1 秒 = 1 天），<strong>仅限测试环境</strong></li></ul><h2 id="五、现场演示" tabindex="-1">五、现场演示 <a class="header-anchor" href="#五、现场演示" aria-label="Permalink to &quot;五、现场演示&quot;">​</a></h2><p>演讲者进行了实时演示，展示了以下流程：</p><ol><li>使用 <code>rclone</code> 向 bucket 上传不同大小的文件</li><li>观察对象根据 2 MB 阈值分别落入 <strong>warm data pool</strong>（小对象，replicated）和 <strong>hot data pool</strong>（大对象，EC）</li><li>15 秒后（对应 lifecycle 配置的 15 天）触发过渡，约 1 GB 数据迁移至 <strong>S3 archive pool</strong></li><li>运行 GC（garbage collector）命令，清理原 pool 中的旧数据</li><li>30 秒后（对应 30 天）对象被 expire 删除，archive pool 清空</li></ol><p>演示从德国远程连接到集群完成，展示了 Ceph 跨地域管理的可行性。</p><h2 id="六、最佳实践建议-来自社区经验" tabindex="-1">六、最佳实践建议（来自社区经验） <a class="header-anchor" href="#六、最佳实践建议-来自社区经验" aria-label="Permalink to &quot;六、最佳实践建议（来自社区经验）&quot;">​</a></h2><p>基于 VM backup and replication 软件的实际使用经验，推荐以下配置策略：</p><ul><li><strong>使用 Amazon 标准 storage class 名称</strong>（如 <code>STANDARD</code>、<code>STANDARD_IA</code>、<code>DEEP_ARCHIVE</code>），以确保与 S3 客户端的兼容性</li><li>对于小 64 KB 的对象，使用 <code>STANDARD</code> storage class，映射到 NVMe SSD 上的 replicated pool</li><li>对于较大的对象，使用 <code>STANDARD_IA</code> storage class，映射到 HDD 或混合驱动器上的 pool</li><li>将 <code>STANDARD</code> 设置为默认 storage class，确保小对象始终获得最优性能</li></ul><h2 id="七、致谢" tabindex="-1">七、致谢 <a class="header-anchor" href="#七、致谢" aria-label="Permalink to &quot;七、致谢&quot;">​</a></h2><p>演讲者特别感谢以下贡献者：</p><ul><li><strong>Casey、Eric、Matt</strong>：长期维护 RGW</li><li><strong>Greg Farnum</strong>：多年来对 RGW 的持续贡献</li><li><strong>Yubo</strong>：在 radosgw 中实现 Lua scripting 支持</li><li><strong>Matthew Eller</strong>：本周实现 lifecycle 过渡时的压缩/解压缩功能</li><li><strong>Stephen Ambio</strong>（OS Nixis）：RGW zoning 相关工作</li><li><strong>Anthony Dri 和 Kurt Burns</strong>：RGW scripting 演讲</li><li><strong>Casperis</strong>：分享 VM backup and replication 与 S3 storage 结合使用的实战经验</li></ul>',53)])])}const g=a(t,[["render",r]]);export{h as __pageData,g as default};
